sys_script.script:
(function executeRule(current, previous) {

    var DEADLINE_TABLE =
        'x_snc_campusmatch_campusmatch_deadline';

    var newStatus = '';

    /* Successfully collected */
    if (current.handover_completed.changesTo(true)) {
        newStatus = 'completed';
    }

    /* Student withdrew */
    else if (current.claim_status.changesTo('Withdrawn')) {
        newStatus = 'cancelled';
    }

    /* Claim rejected/cancelled */
    else if (
        current.claim_status.changesTo('Rejected') ||
        current.claim_status.changesTo('Cancelled')
    ) {
        newStatus = 'cancelled';
    }

    if (!newStatus)
        return;


    var deadline = new GlideRecord(DEADLINE_TABLE);

    deadline.addQuery('claim', current.getUniqueValue());
    deadline.addQuery('deadline_type', 'collection');
    deadline.addQuery('status', 'active');
    deadline.query();

    while (deadline.next()) {
        deadline.setValue('status', newStatus);
        deadline.update();
    }

})(current, previous);
